// (Module 5 still said "6 lessons" after espresso was written.)
MODULES.forEach(function (m) {
  var r = MODULE_REWARDS[m.id];
  if (!r) return;
  r.meta = [['MODULE', String(m.n).padStart(2, '0') + ' \xB7 ' + m.title], ['LESSONS', String(m.lessons.length)],
  // The rule since #608: a Field Guide is earned when every lesson in the
  // module has a perfect best, not when the module is finished.
  ['EARNED BY', 'Every lesson perfect']];
});

// One card, one text. The reward screen renders LESSONS[id].reward (or
// MODULE_REWARDS); the collection sheet renders the COLLECTIBLES entry. The words
// are authored once and copied across here, at load, before any render.
function syncCardText() {
  COLLECTIBLES.forEach(function (c) {
    if (!c.unlock) return;
    var src = c.unlock.lesson ? (LESSONS[c.unlock.lesson] || {}).reward : c.unlock.module ? MODULE_REWARDS[c.unlock.module] : null;
    if (!src) return;
    ['title', 'summary', 'fact', 'meta'].forEach(function (k) {
      if (src[k] != null) c[k] = src[k];
    });
  });
}
// Translated course content (content-i18n.js). Before syncCardText, so the
